const eye = all.filter(e => e.tagName==='BR-BUTTON' && e.getAttribute('icon')==='eye').slice(0,1).map(b=>({host:b.outerHTML.slice(0,300), parent: b.parentElement.outerHTML.slice(0,400), inner: b.shadowRoot && b.shadowRoot.innerHTML.slice(0,400)}));
